import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";

const request = (id, units, extra = {}) => ({
  action:"book", service:"studio", tenant:"orchid", day:"2025-04-02", id, units, ...extra
});
const renewal = (previous, id, extra = {}) => ({
  action:"renew", service:"studio", previous, id, day:"2025-05-02", ...extra
});

test("studio quota accounts by tenant and day, without changing Archive", () => {
  const dispatch = planner(readCatalog());
  assert.deepEqual(dispatch(request("morning", 3)), {status:"booked", id:"morning", remaining:5});
  assert.deepEqual(dispatch(request("evening", 5)), {status:"booked", id:"evening", remaining:0});
  assert.deepEqual(dispatch(request("overflow", 1)), {status:"full", id:"overflow", remaining:0});
  assert.equal(dispatch(request("tomorrow", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(request("iris", 5, {tenant:"iris"})).status, "booked");
  assert.deepEqual(dispatch(request("iris-full", 1, {tenant:"iris"})),
    {status:"full", id:"iris-full", remaining:0});
  assert.equal(dispatch(request("archive", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(request("archive", 5, {service:"archive"})).status, "booked");
  assert.equal(dispatch(renewal("archive", "archive-next", {service:"archive", units:6})).status, "full");
  assert.equal(dispatch(renewal("archive", "archive-next", {service:"archive"})).status, "booked");
});

test("replays, conflicts and cancellations precede Studio admission", () => {
  const dispatch = planner(readCatalog());
  const original = request("original", 8);
  dispatch(original);
  assert.deepEqual(dispatch(original), {status:"replay", id:"original"});
  assert.equal(dispatch({...original, units:7}).status, "conflict");
  assert.equal(dispatch({...original, tenant:"iris"}).status, "conflict");
  assert.equal(dispatch({...original, day:"2025-04-03"}).status, "conflict");
  assert.equal(dispatch({action:"cancel", service:"studio", id:"original"}).status, "cancelled");
  assert.equal(dispatch(original).status, "cancelled");
  assert.equal(dispatch(request("replacement", 8)).status, "booked");
  assert.equal(dispatch({action:"cancel", service:"studio", id:"original"}).status, "replay");
  const summary = dispatch({action:"summary", service:"studio"});
  assert.equal(summary.events.length, 3);
  assert.deepEqual(summary.occupied.map(row => row.id), ["replacement"]);
});

test("monthly renewals share the quota and retain renewal replay semantics", () => {
  const dispatch = planner(readCatalog());
  dispatch(request("original", 7));
  dispatch(request("may-other", 1, {day:"2025-05-02"}));
  assert.deepEqual(dispatch(renewal("original", "may")), {status:"booked", id:"may", remaining:0});
  assert.deepEqual(dispatch(renewal("original", "may")), {status:"replay", id:"may"});
  assert.equal(dispatch(renewal("original", "may", {units:6})).status, "conflict");
  assert.equal(dispatch(renewal("original", "too-many")).status, "full");
  dispatch({action:"cancel", service:"studio", id:"may"});
  assert.equal(dispatch(renewal("original", "may")).status, "cancelled");
  assert.deepEqual(dispatch(renewal("original", "smaller", {units:6})),
    {status:"booked", id:"smaller", remaining:1});
  dispatch({action:"cancel", service:"studio", id:"original"});
  assert.equal(dispatch(renewal("original", "missing")).status, "missing");
  assert.equal(dispatch(renewal("unknown", "missing")).status, "missing");
});

test("lower allocations, fallback, imported usage and validation also apply to renewals", () => {
  const dispatch = planner({default:5, studios:new Map([["orchid", 3]])});
  assert.equal(dispatch(request("too-big", 4)).status, "full");
  dispatch(request("original", 3));
  assert.equal(dispatch(renewal("original", "too-big", {units:4})).status, "full");
  assert.equal(dispatch(request("fallback", 5, {tenant:"iris"})).status, "booked");
  assert.equal(dispatch(renewal("fallback", "fallback-next")).status, "booked");
  assert.equal(dispatch(renewal("fallback", "fallback-full", {units:1})).status, "full");
  assert.equal(dispatch(request("backfill", 10, {action:"import", day:"2025-04-03"})).status, "imported");
  assert.deepEqual(dispatch(request("over-import", 1, {day:"2025-04-03"})),
    {status:"full", id:"over-import", remaining:0});
  assert.equal(apply(dispatch, request("invalid", 0)).status, "invalid");
  assert.equal(apply(dispatch, renewal("original", "invalid", {units:0})).status, "invalid");
  assert.equal(dispatch({action:"lookup", service:"studio", id:"invalid"}), null);
});
